#!/usr/bin/env python3
"""Render the measured first bridge milestone, keeping unqualified work explicit."""
from pathlib import Path
import html
import json

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'docs/proposition/analyse/v6'
receipt = json.loads((OUT / 'pont-ha-moli-tests.json').read_text())
if receipt['status'] != 'PASS':
    raise SystemExit('Le rendu final exige un reçu de qualification réussi.')
esc = lambda value: html.escape(str(value))


def table(headers, rows):
    return '<div class="table-wrap"><table><thead><tr>' + ''.join(
        '<th>' + esc(value) + '</th>' for value in headers) + '</tr></thead><tbody>' + ''.join(
            '<tr>' + ''.join('<td>' + esc(value) + '</td>' for value in row) + '</tr>'
            for row in rows) + '</tbody></table></div>'


css = (OUT / 'index.html').read_text().split('<style>', 1)[1].split('</style>', 1)[0]
rows = [[name, data['passed'], data['failed'], data['ignored']]
        for name, data in receipt['rust_packages'].items()]
total = sum(data['passed'] for data in receipt['rust_packages'].values())
checks = table(['Contrôle', 'Résultat', 'Durée'], [
    [row['name'], row['status'], str(row['seconds']) + ' s'] for row in receipt['checks']])
page = '''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>V6 · Pont Home Assistant et migration : premier lot</title><style>''' + css + '''</style></head><body><div class="wrap"><header class="hero"><p class="eyebrow">Moli · Premier lot expérimental · 28 octobre 2026</p><h1>HA garde ses automatismes.<br>Moli prépare la reprise des appareils.</h1><p class="intro">Les briques de pont MQTT, de garde native et de migration durable sont créées. Le chemin vers Overkiz est validé en simulation. La neutralisation d’un HA réel et la migration de ses automatismes restent fermées.</p></header><p class="note"><a href="index.html">Dossier V6</a> · <a href="pont-ha-moli-tests.json">Résultats et empreintes de code</a> · <a href="pont-ha-moli-preuves.json">Registre des preuves</a> · <a href="../../../components/home-assistant.md">Configuration et limites</a></p><main class="main">
<section class="section"><h2>Ce qui est créé</h2>''' + table(['Brique', 'Responsabilité'], [
    ['moli-home-assistant', 'Messages versionnés, catalogue et états HA typés, commandes MQTT dans les deux sens, sessions et échéances'],
    ['moli-migration', 'Correspondances stables, empreinte du plan, révision, phases durables, retour inverse et réconciliation'],
    ['moli-runtime', 'Autorité par génération sur tous les chemins de commande ; instances natives fermées avant découverte'],
    ['moli-overkiz / moli-net', 'Permis vivant jusqu’au dernier envoi HTTP, après connexion, TLS et attente OAuth'],
    ['Compagnon HA moli', 'Inventaire HA, proxies cover sans optimisme RTS, bouton favori et résultats MQTT'],
    ['Application et API Moli', 'Préparation avant pilotes, activation explicite, routes protégées, sauvegarde de migration.json']]) + '''<p>Les identifiants de registre et de point restent des clés ; les noms sont des descriptions. Un appareil température/humidité conserve deux canaux, deux valeurs, deux unités et deux sémantiques. Les tables de choix enum sont froides, les états transportent le code sélectionné. Les proxies Moli sont exclus de l’inventaire renvoyé par HA.</p><p>Un ordre HA entre sous <code>Origin::Api</code>, jamais comme un humain Moli ou un automatisme approuvé sur la foi du payload. La garde, les pièces protégées, les échéances et les générations restent appliquées dans le Hub et dans le pilote natif.</p></section>
<section class="section"><h2>Ce qui a réellement été testé</h2><p><strong>''' + str(total) + ''' tests Rust réussis</strong> sur les paquets ci-dessous, avec contrôles de format et Clippy stricts. Ces effectifs comprennent des tests existants, des tests d’intégration et, selon le paquet, des doctests ; ils ne représentent pas autant de nouveaux tests.</p>''' + table(['Paquet', 'Réussis', 'Échecs', 'Ignorés'], rows) + '''<p>Les trois scénarios intégrés Overkiz utilisent un faux HA publiant sur un véritable broker MQTT Aedes authentifié en loopback, le vrai pilote HomeAssistant Rust, le vrai Hub et la vraie boucle Overkiz devant une box en mémoire. Aucun CONNECT n’est normalisé pour contourner le protocole ; le testament MQTT offline est également observé.</p><ul><li>Transfert simulé puis ouvrir → stop → fermer et favori : ordre conservé, une seule arrivée à la box simulée, aucune position RTS inventée.</li><li>Pièce protégée, tentative d’origine humaine dans le JSON, expiration, doublon et anciennes générations : refus sans effet supplémentaire.</li><li>Rejeu retained à la souscription avec nonce courant : refus ; commande live suivante acceptée ; arrêt et testament offline.</li></ul><p>Les tests du registre couvrent notamment les empreintes et révisions, les preuves incompatibles, le retour inverse, la fermeture au redémarrage, la nouvelle preuve après rechargement, les erreurs avant/après renommage et les bornes. Ceux du Hub couvrent la révocation, la non-résurrection d’un permis, l’approbation différée et l’absence de cycle de rétention.</p><p><strong>22 tests Python purs et5 tests avec Home Assistant ''' + esc(receipt['home_assistant_version']) + ''' réussis.</strong> Le second groupe emploie les vrais objets HA, registres, bus et services dans un dossier temporaire ; seule l’I/O MQTT y est doublée. Il vérifie les abonnements, le démarrage tardif et les nonces, les canaux distincts et enums, le callback cover vers MQTT et le dispatch inverse vers un service HA. Le runtime HA d’une maison n’est pas exécuté par ces tests.</p><p>Une fixture commune est lue par Rust et Python : elle épingle les identités, le hash canonique des correspondances et les enveloppes dans les deux sens.</p></section>
<section class="section"><h2>Corrections éprouvées pendant ce lot</h2><ul><li>Overkiz perdait le permis vivant après la séparation de la tâche d’envoi ; il l’emporte maintenant jusqu’à la frontière HTTP.</li><li>Les commandes admises dans une ancienne génération ne peuvent pas être réactivées après un aller-retour de propriétaire.</li><li>Les imports Python absolus et l’abonnement de commande inversé étaient masqués par les seuls tests purs ; le chargement avec le vrai framework les a révélés.</li><li>L’accès au registre d’appareils HA utilise maintenant la résolution par identifiant, et les preuves de migration reprennent le nonce du consommateur Moli.</li><li>Un état retained explicitement indisponible ne rend plus le proxy disponible. Position et fermeture restent inconnues sans feedback observé.</li><li>Les battements live5s expirent après15s ; un ancien birth retained ne renouvelle pas la disponibilité.</li></ul></section>
<section class="section"><h2>Bascule et autorité</h2><p>Le registre est préparé avant tous les pilotes natifs. Une instance déclarée sous migration démarre fermée, même pour un appareil encore inconnu. Pour passer vers Moli : préparer → observer l’ancien écrivain arrêté et quiescent → accorder le nouveau propriétaire après décision durable. Le retour vers HA suit les phases inverses. Une erreur de transport ne change jamais le propriétaire.</p><p>Une erreur de stockage après renommage produit un état incertain : fermeture, rechargement et défi neuf, sans rollback aveugle ni répétition. Une fermeture d’urgence ne réouvre jamais la même génération. Les identités, versions et empreintes empêchent une ancienne preuve de valider un autre plan.</p><p>L’API expose lecture, prepare, advance, reconcile et reload. Les mutations exigent une session humaine avec PIN, refusent invités et mode démo, et limitent les corps à8Kio. Aucune route HTTP ne permet de faire acquitter une preuve par un booléen. Le registre global est sauvegardé et restauré avec les données Moli.</p></section>
<section class="section"><h2>Ce qui reste non qualifié ou non implémenté</h2><ul><li><strong>Neutralisation HA réelle :</strong> aucune config entry n’est modifiée par le compagnon. Son observateur fiable n’est pas branché par défaut ; le statut <code>quiescence_not_proven</code> bloque la bascule.</li><li><strong>Automatismes, scripts et scènes :</strong> pas d’import actif, pas de réécriture des références existantes ni de transfert du moteur. La provenance structurée préparée reste celle d’un brouillon inactif.</li><li><strong>Identités HA existantes :</strong> les proxies ont leurs propres identifiants stables ; leur adoption dans les anciens automatismes est un jalon distinct.</li><li><strong>Matériel :</strong> aucune box réelle ni pièce habitée n’a reçu d’ordre pour cette qualification. Une cible neutre et une validation encadrée restent nécessaires.</li><li><strong>Exploitation continue :</strong> les files sont bornées ;256reçus par session sans éviction silencieuse. Le renouvellement et la charge prolongée de ce nouveau pont restent à qualifier.</li><li><strong>Déploiement :</strong> le compagnon n’est pas installé sur les deux HA, et le nouveau module n’est pas activé dans le POC1414. Les services existants n’ont pas été redémarrés.</li><li><strong>Fraîcheur :</strong> disponibilité du lien et état rapporté par HA ne prouvent pas la fraîcheur physique d’un retained. Aucun retour RTS n’est fabriqué à partir d’un acquittement.</li></ul><p>Il s’agit du premier jalon de construction et de qualification simulée. Ce dossier ne présente pas le pont complet de migration comme déployé ou la reprise des automatismes comme achevée.</p></section>
<section class="section"><h2>Reproduire et relire</h2><pre><code>python3 tools/home-assistant/check-moli-bridge.py</code></pre>''' + checks + '''<p>Code : <a href="../../../../crates/moli-home-assistant/src/lib.rs">pont Rust</a>, <a href="../../../../crates/moli-migration/src/lib.rs">registre</a>, <a href="../../../../tools/home-assistant/custom_components/moli/bridge.py">compagnon HA</a>, <a href="../../../../crates/moli-overkiz/src/bridge_tests.rs">tests MQTT/Hub/Overkiz</a>. <a href="../../pont-home-assistant-moli-v1.md">Contrat du lot</a>.</p><p>Contrats externes : <a href="https://contributors.home-assistant.io/core/entities/cover/">CoverEntity</a> et <a href="https://github.com/home-assistant/core/blob/dev/homeassistant/components/mqtt/client.py">client MQTT HA</a>. Les résultats de ce dossier sont liés au code testé et au framework installé, pas à une simple relecture de ces sources.</p></section></main></div></body></html>'''
(OUT / 'pont-ha-moli.html').write_text(page)
print('Rapport du premier lot HA/Moli rendu depuis les tests.')
